```go
package main

import (
	"encoding/json"
	"fmt"
)

type User struct {
	ID          int    `json:"id"`
	DisplayName string `json:"display_name"`
	Secret      string `json:"-"`
	note        string
}

func main() {
	b, err := json.Marshal(User{ID: 3, DisplayName: "Kai", Secret: "x", note: "hidden"})
	if err != nil {
		panic(err)
	}
	fmt.Println(string(b))
}
```
Secret is explicitly excluded and note is unexported, so neither becomes part of the JSON object.

```go
package main

import (
	"encoding/json"
	"fmt"
	"strings"
)

type User struct {
	Name string `json:"name"`
}

func main() {
	input := `{"name":"Mira","admin":true}`
	var permissive User
	if err := json.Unmarshal([]byte(input), &permissive); err != nil {
		panic(err)
	}
	dec := json.NewDecoder(strings.NewReader(input))
	dec.DisallowUnknownFields()
	var strict User
	err := dec.Decode(&strict)
	fmt.Println(permissive.Name, err != nil)
}
```
Unmarshal accepts and discards admin; the configured Decoder rejects it as an unknown field.

```go
package main

import (
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"strings"
)

type CreateUser struct {
	Name string `json:"name"`
	Age  *int   `json:"age"`
}

func parse(text string) (CreateUser, error) {
	dec := json.NewDecoder(strings.NewReader(text))
	dec.DisallowUnknownFields()
	var in CreateUser
	if err := dec.Decode(&in); err != nil {
		return in, err
	}
	var extra any
	if err := dec.Decode(&extra); err != io.EOF {
		return in, errors.New("expected one JSON value")
	}
	if strings.TrimSpace(in.Name) == "" {
		return in, errors.New("name is required")
	}
	if in.Age == nil || *in.Age < 0 {
		return in, errors.New("valid age is required")
	}
	return in, nil
}

func main() {
	u, err := parse(`{"name":"Ada","age":0}`)
	fmt.Println(u.Name, *u.Age, err)
}
```
The pointer records that age was supplied even when its valid value is zero; validation remains separate from decoding.
